	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");
scwin.contnId;
scwin.notiObjSysCode;
scwin.vScrenID = "ULDSTF90400.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_code1_sync = function() {
    //var url1= "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ENG_NM=NOTI_OBJ_SYS_TP_CD"; 

    //MxDataSet_code1.DataID = encodeURI(url1);

    //MxDataSet_code1.reset(); 

};
scwin.fn_list_sync = function() {
    var KeyWord = keyword.getValue();
    var Condition1 = $c.cp.valueOfIndex(MxCombo_1, "VALUE", MxCombo_1.getSelectedIndex());
    //var Condition2 = MxDataSet_code1.NameString((cb_system_gbn.Index+1),"CD_VAL");
    url = "/NoticeContent.do?method=listHelpContent";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&keyword=" + KeyWord;
    url += "&Condition1=" + Condition1;
    url += "&Condition2=3";
    dts_noticeList.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_noticeList.reset();
    $c.cm.ShowWin(MxGrid_2);
};
scwin.dts_noticeList_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, MxGrid_2); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.MxGrid_2_OnDblClick = function(row, colid) {
    if (colid == 'SAVE_FILE_NM') {
        var screnId = dts_noticeList.getCellData(row, "SCREN_ID");
        location.href = "/filedownload.do?SCREN_ID=" + screnId + "&gubun=35";
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
    MxCombo_1.setSelectedIndex(0);
    //MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";
    //MxDataSet_code1.reset();

    //fn_code1_sync() ;

};
scwin.bnt_Select_onclick = function() {
    scwin.fn_list_sync();
};
scwin.keyword_onkeydown = function() {
    if (window.event.keyCode == "13") {
        scwin.fn_list_sync();
    }
};
